class Solution:
    def maxTotal(self, value: List[int], limit: List[int]) -> int:
        total = active = 0
        for l, v in sorted(zip(limit, value)):
            if l > active:
                total += v
                active += 1
        return total

c.cpp:
class Solution {
public:
    long long maxTotal(vector<int>& value, vector<int>& limit) {
        int n = value.size();
        vector<pair<int,int>> a(n);
        for (int i = 0; i < n; i++) a[i] = {limit[i], value[i]};
        sort(a.begin(), a.end());
        long long total = 0; int active = 0;
        for (auto& [l, v] : a)
            if (l > active) { total += v; active++; }
        return total;
    }
};

