class Solution {
    public long maxTotal(int[] value, int[] limit) {
        int n = value.length;
        int[][] a = new int[n][2];
        for (int i = 0; i < n; i++) { a[i][0] = limit[i]; a[i][1] = value[i]; }
        Arrays.sort(a, (x, y) -> x[0] != y[0] ? x[0] - y[0] : x[1] - y[1]);
        long total = 0; int active = 0;
        for (int[] p : a)
            if (p[0] > active) { total += p[1]; active++; }
        return total;
    }
}

