var maxTotal = function(value, limit) {
    const a = value.map((v, i) => [limit[i], v]).sort((x, y) => x[0] - y[0] || x[1] - y[1]);
    let total = 0, active = 0;
    for (const [l, v] of a)
        if (l > active) { total += v; active++; }
    return total;
};
